<template>
  <div class="page-container" v-if="renderDataList">
    <!-- Page Header with Group Name and Actions -->
    <div class="row justify-between items-center back-white q-pa-sm">
      <div class="row items-center gap-2">
        <q-btn
          flat
          dense
          round
          icon="arrow_back"
          data-test="access-control-back-button"
          :aria-label="$t('back_to_groups')"
          @click="goBackToGroups"
        >
          <q-tooltip>{{ $t('back_to_groups') }}</q-tooltip>
        </q-btn>
        <h1 class="text-h5 q-ma-none">{{ groupName }}</h1>
      </div>
      <f-btn :label="$t('save')" @click="save" size="sm" />
    </div>

    <q-splitter
      v-model="splitterModel"
      horizontal
      :limits="[20, 80]"
      class="page-height-100-135"
      separator-class="splitter-separator"
    >
      <template v-slot:before>

        <!-- Document Level Permissions Table -->
          <q-markup-table class="full-width scrollable-table table-style back-white" flat >
            <thead>
              <tr>
                <th class="doc-type-header">{{ $t('document_type') }}</th>
                <th v-for="column in permissionColumns" :key="column.name" class="permission-header">
                  <div class="column-header">
                    <span>{{ $t(column.label) }}</span>
                    <q-icon name="info_outline" size="14px" class="info-icon">
                      <q-tooltip anchor="bottom middle" self="top middle" :offset="[0, 8]" class="permission-tooltip">
                        {{ $t(`${column.name}_tooltip`) }}
                      </q-tooltip>
                    </q-icon>
                  </div>
                </th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="doc in documentList"
                :key="doc.id"
                :class="{
                  'disabled-row': apiData[groupId]?.[doc.document_key]?.access !== AccessStatus.ENABLED,
                  'selected-row': selectedDocument?.document_key === doc.document_key
                }"
              >
                <!-- Document Name (clickable) -->
                <td>
                  <span
                    :class="[
                      'doc-name',
                      apiData[groupId]?.[doc.document_key]?.access !== AccessStatus.ENABLED ? 'disabled' : ''
                    ]"
                    @click="selectDocument(doc)"
                  >
                    {{ doc.title }}
                    <q-tooltip v-if="apiData[groupId]?.[doc.document_key]?.access === AccessStatus.ENABLED">
                      {{ $t('click_to_set_field_level_permissions') }}
                    </q-tooltip>
                  </span>
                </td>

                <!-- Access Toggle Button -->
                <td>
                  <button
                    :class="[
                      'access-badge',
                      apiData[groupId]?.[doc.document_key]?.access === AccessStatus.ENABLED ? 'enabled' : 'disabled'
                    ]"
                    @click="toggleAccess(doc)"
                  >
                    <q-icon
                      :name="apiData[groupId]?.[doc.document_key]?.access === AccessStatus.ENABLED ? 'check' : 'close'"
                      size="14px"
                    />
                    {{ apiData[groupId]?.[doc.document_key]?.access === AccessStatus.ENABLED ? $t('enabled') : $t('disabled') }}
                  </button>
                </td>

                <!-- Other Permission Selects -->
                <td v-for="column in permissionColumns.slice(1)" :key="column.name">
                  <q-select
                    v-model="permissionFor(doc)[column.name]"
                    :options="column.name === 'access' ? accessOptionList : listOption"
                    :disable="permissionFor(doc).access !== AccessStatus.ENABLED"
                    :class="getSelectClass(permissionFor(doc)[column.name], permissionFor(doc).access !== AccessStatus.ENABLED)"
                    borderless
                    dense
                    emit-value
                    map-options
                    hide-dropdown-icon
                    options-dense
                  >
                    <template v-slot:option="scope">
                      <q-item v-bind="scope.itemProps">
                        <q-item-section>
                          <q-item-label>
                              <q-icon
                              v-if="scope.opt.value === permissionFor(doc)[column.name]"
                              name="check"
                              class="q-mr-sm"
                              color="primary"
                            />
                            {{ scope.opt.label }}
                          </q-item-label>
                        </q-item-section>
                      </q-item>
                    </template>
                  </q-select>
                </td>
              </tr>

              <!-- Unclassified: permissions for documents not yet classified.
                   Always enabled (no toggle); Everyone/Owner only; no approvals. -->
              <tr class="unclassified-row">
                <td>
                  <span class="doc-name-static">{{ $t('unclassified') }}</span>
                </td>

                <!-- Access: always enabled, cannot be disabled -->
                <td>
                  <span class="access-badge enabled locked">
                    <q-icon name="check" size="14px" />
                    {{ $t('enabled') }}
                    <q-tooltip>{{ $t('unclassified_tooltip') }}</q-tooltip>
                  </span>
                </td>

                <!-- Only list/view/edit/delete/mass_update; no approvals -->
                <td v-for="column in permissionColumns.slice(1)" :key="column.name">
                  <q-select
                    v-if="!isApprovalColumn(column.name)"
                    v-model="unclassifiedPermission()[column.name]"
                    :options="unclassifiedOptions"
                    :class="getSelectClass(unclassifiedPermission()[column.name], false)"
                    borderless
                    dense
                    emit-value
                    map-options
                    hide-dropdown-icon
                    options-dense
                  >
                    <template v-slot:option="scope">
                      <q-item v-bind="scope.itemProps">
                        <q-item-section>
                          <q-item-label>
                            <q-icon
                              v-if="scope.opt.value === unclassifiedPermission()[column.name]"
                              name="check"
                              class="q-mr-sm"
                              color="primary"
                            />
                            {{ scope.opt.label }}
                          </q-item-label>
                        </q-item-section>
                      </q-item>
                    </template>
                  </q-select>
                </td>
              </tr>
            </tbody>
          </q-markup-table>
      </template>

      <template v-slot:after>
        <!-- Field Permissions Detail Component (embedded mode) -->
        <AccessControlDetail
          :embedded="true"
          :documentKey="selectedDocument?.document_key || ''"
          :groupIdProp="groupId"
          :groupNameProp="groupName"
          @close="closeFieldPermissions"
        />
      </template>
    </q-splitter>
  </div>

  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import AccessControlDetail from './Detail.vue';
import type { dynamicObj } from 'src/pages/assets';
import { supplierDocTypeKey } from 'src/constants';
import { ApiExceptions } from 'src/exceptions/index';
import { useDocPermissionsStore } from 'src/store/main';
import { filterApiDocTypes } from 'src/utils/docTypeFilter';
import { documentTypeApiService } from 'src/services/index';
import { notify } from 'src/components/notifications/notify';
import { AccessStatus, PermissionLevel } from 'src/core/acls/Acl';

// Pseudo doc-type key for permissions applied to documents that are not yet
// classified. Rendered as an extra, always-enabled row.
const UNCLASSIFIED_KEY = 'UNCLASSIFIED';

export default defineComponent({
  el: '#app',
    components: {
    AccessControlDetail,
  },
  async mounted() {
    await this.init();
  },
  data() {
    return {
      splitterModel: 50,
      permissionColumns: [
        { label: 'access', name: 'access' },
        { label: 'list', name: 'list' },
        { label: 'view', name: 'view' },
        { label: 'edit', name: 'edit' },
        { label: 'delete', name: 'delete' },
        { label: 'mass_update', name: 'mass_update' },
        { label: 'first_approval', name: 'first_approval' },
        { label: 'second_approval', name: 'second_approval' },
        // { label: 'unlock_document', name: 'unlock_document' },
      ],
      renderDataList: ref(false),
      documentList: [] as dynamicObj[],
      groupId: this.$route.params.id as string,
      groupName: this.$route.params.group_name as string,
      selectedDocument: null as dynamicObj | null,
    };
  },
  computed: {
    // Unclassified only supports Everyone and Owner.
    unclassifiedOptions(): dynamicObj[] {
      return this.listOption.filter(
        (o: dynamicObj) =>
          o.value === PermissionLevel.FULL || o.value === PermissionLevel.OWNER,
      );
    },
  },
  methods: {
    isApprovalColumn(name: string): boolean {
      return name === 'first_approval' || name === 'second_approval';
    },
    // Permission entry for the always-enabled Unclassified row. Forces access
    // to ENABLED (it can never be disabled) and keeps each level within the two
    // allowed values (Everyone/Owner), defaulting to Owner.
    unclassifiedPermission(): dynamicObj {
      if (!this.apiData[this.groupId]) {
        this.apiData[this.groupId] = {};
      }
      if (!this.apiData[this.groupId][UNCLASSIFIED_KEY]) {
        this.apiData[this.groupId][UNCLASSIFIED_KEY] = {
          access: AccessStatus.ENABLED,
          list: PermissionLevel.OWNER,
          view: PermissionLevel.OWNER,
          edit: PermissionLevel.OWNER,
          delete: PermissionLevel.OWNER,
          mass_update: PermissionLevel.OWNER,
          first_approval: PermissionLevel.NO_ACCESS,
          second_approval: PermissionLevel.NO_ACCESS,
        };
      }
      const entry = this.apiData[this.groupId][UNCLASSIFIED_KEY];
      // Always enabled — never allow disable.
      if (entry.access !== AccessStatus.ENABLED) {
        entry.access = AccessStatus.ENABLED;
      }
      // Clamp to the two allowed levels so the select always shows a valid one.
      for (const key of ['list', 'view', 'edit', 'delete', 'mass_update']) {
        if (
          entry[key] !== PermissionLevel.FULL &&
          entry[key] !== PermissionLevel.OWNER
        ) {
          entry[key] = PermissionLevel.OWNER;
        }
      }
      return entry;
    },
    async init() {
      try {
        this.processing = true;
        await this.getDocTypes();
        await this.fetchAllDocTypeSettings();
      } catch (error: any) {
        logError(error);
      } finally {
        this.renderDataList = true;
        this.processing = false;
      }
    },
    goBackToGroups() {
      this.$router.push({
        path: '/settings/roles',
        query: { selectedGroupId: this.groupId },
      });
    },
    async getDocTypes() {
      try {
        const response = await documentTypeApiService.fetchDocTypes();
        if (!response.success) {
          throw response?.message;
        }
        this.documentList = filterApiDocTypes(response.data, {
          activeOnly: true,
          excludeByKey: supplierDocTypeKey,
        });
      } catch (error: any) {
        logError(error);
      }
    },
    async fetchAllDocTypeSettings() {
      try {
        await this.getAllDocTypeSettings(this.groupId);
        this.mappedPermissionToDocument(this.documentList);
      } catch (error: any) {
        logError(error);
      }
    },
    async save() {
      const dataObject: any = {
        [this.groupId]: {},
      };
      this.documentList.forEach((document: any) => {
        const permission = this.permissionFor(document);
        dataObject[this.groupId][document.document_key] = {
          access: permission.access,
          list: permission.list,
          view: permission.view,
          edit: permission.edit,
          delete: permission.delete,
          mass_update: permission.mass_update,
          first_approval: permission.first_approval,
          second_approval: permission.second_approval,
          // unlock_document: permission.unlock_document,
        };

        // Include field permissions if they exist
        if (permission.fields) {
          dataObject[this.groupId][document.document_key]['fields'] =
            permission.fields;
        }
      });

      // Unclassified: always enabled; only list/view/edit/delete/mass_update
      // apply (no approvals).
      const unclassified = this.unclassifiedPermission();
      dataObject[this.groupId][UNCLASSIFIED_KEY] = {
        access: AccessStatus.ENABLED,
        list: unclassified.list,
        view: unclassified.view,
        edit: unclassified.edit,
        delete: unclassified.delete,
        mass_update: unclassified.mass_update,
        first_approval: PermissionLevel.NO_ACCESS,
        second_approval: PermissionLevel.NO_ACCESS,
      };
      try {
        this.processing = true;
        const jsonData = JSON.stringify(dataObject);
        await this.updateDocTypeSetting(jsonData);
        await this.fetchAllDocTypeSettings();
        notify.success(this.$t('save_successfully'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    toggleAccess(doc: dynamicObj) {
      const permission = this.permissionFor(doc);
      permission.access = permission.access === AccessStatus.ENABLED ? AccessStatus.DISABLED : AccessStatus.ENABLED;
    },
    selectDocument(doc: dynamicObj) {
      if (this.selectedDocument?.document_key === doc.document_key) {
        this.closeFieldPermissions();
        return;
      }
      this.selectedDocument = doc;
    },
    closeFieldPermissions() {
      this.selectedDocument = null;
    },
    getSelectClass(value: number | undefined, isDisabled: boolean): string {
      if (isDisabled) return 'permission-select disabled';
      switch (value) {
        case PermissionLevel.NO_ACCESS:
          return 'permission-select no-access';
        case PermissionLevel.FULL:
          return 'permission-select everyone';
        case PermissionLevel.OWNER:
          return 'permission-select owner';
        case PermissionLevel.ASSIGNEE:
          return 'permission-select assignee';
        case PermissionLevel.OWNER_ASSIGNEE:
          return 'permission-select owner-assignee';
        default:
          return 'permission-select';
      }
    },
    permissionFor(doc: dynamicObj): dynamicObj {
      if (!this.apiData[this.groupId]) {
        this.apiData[this.groupId] = {};
      }
      const entry = this.apiData[this.groupId][doc.document_key];
      if (!entry) {
        this.apiData[this.groupId][doc.document_key] = {
          access: AccessStatus.DISABLED,
          list: PermissionLevel.NO_ACCESS,
          view: PermissionLevel.NO_ACCESS,
          edit: PermissionLevel.NO_ACCESS,
          delete: PermissionLevel.NO_ACCESS,
          mass_update: PermissionLevel.NO_ACCESS,
          first_approval: PermissionLevel.NO_ACCESS,
          second_approval: PermissionLevel.NO_ACCESS,
          // unlock_document: PermissionLevel.NO_ACCESS,
        };
      } else {
        // API row exists but may be missing individual action keys — fill them
        // with NO_ACCESS so the q-select renders a label instead of going blank.
        const actionKeys = [
          'list', 'view', 'edit', 'delete', 'mass_update',
          'first_approval', 'second_approval', /* 'unlock_document' */
        ];
        for (const key of actionKeys) {
          if (entry[key] === undefined) {
            entry[key] = PermissionLevel.NO_ACCESS;
          }
        }
        if (entry.access === undefined) {
          entry.access = AccessStatus.DISABLED;
        }
      }
      return this.apiData[this.groupId][doc.document_key];
    },
  },
  setup() {
    const permission_store = useDocPermissionsStore();
    const { accessOptionList, listOption, processing, apiData } =
      storeToRefs(permission_store);

    const {
      getAllDocTypeSettings,
      mappedPermissionToDocument,
      updateDocTypeSetting,
    } = permission_store;

    return {
      accessOptionList,
      listOption,
      processing,
      getAllDocTypeSettings,
      mappedPermissionToDocument,
      updateDocTypeSetting,
      apiData,
      AccessStatus,
    };
  },
});
</script>

<style lang="scss" scoped>
.splitter-separator {
  background: #e5e7eb;
  height: 8px !important;

  &:hover {
    background: var(--q-primary);
  }
}

.scrollable-table {
  :deep(thead) {
    position: sticky;
    top: 0;
    z-index: 1;
    background: white;
  }
}

:deep(.q-splitter__before),
:deep(.q-splitter__after) {
  overflow: auto;
}

.doc-type-header {
  text-align: left !important;
  width: 16rem;
}

.permission-header {
  .column-header {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;

    .info-icon {
      color: #9ca3af;
      cursor: help;

      &:hover {
        color: #6b7280;
      }
    }
  }
}

.doc-name {
  cursor: pointer;
  color: var(--q-primary);

  &.disabled {
    color: #9ca3af;
    cursor: not-allowed;
    pointer-events: none;
  }
}

// Unclassified row: label matches the other doc names (primary colour) but is
// not clickable; always-enabled (locked) access badge.
.doc-name-static {
  color: var(--q-primary);
  cursor: default;
}

.access-badge.locked {
  cursor: default !important;

  &:hover {
    background: #dcfce7;
  }
}

// Unclassified row stands out using the org's brand colour (theme-aware via
// color-mix, so it adapts to light/dark automatically).
.unclassified-row td {
  background: color-mix(in srgb, var(--primary) 18%, var(--background));
  border-top: 2px solid color-mix(in srgb, var(--primary) 45%, var(--background));
}

.access-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  border: none;
  cursor: pointer !important;
  transition: all 0.2s;

  &.enabled {
    background: #dcfce7;
    color: #15803d;

    &:hover {
      background: #bbf7d0;
    }
  }

  &.disabled {
    background: #f3f4f6;
    color: #6b7280;

    &:hover {
      background: #e5e7eb;
    }
  }
}

.permission-select {
  min-width: 100px;

  :deep(.q-field__native) {
    border-radius: 0.375rem;
    padding: 0.25rem 0.5rem;
    font-weight: 500;
  }

  &.everyone :deep(.q-field__native) {
    background: #dbeafe;
    color: #1e40af;
  }

  &.owner :deep(.q-field__native) {
    background: #f3e8ff;
    color: #7e22ce;
  }

  &.assignee :deep(.q-field__native) {
    background: #fed7aa;
    color: #c2410c;
  }

  &.owner-assignee :deep(.q-field__native) {
    background: #c5cae9;
    color: #1a237e;
  }

  &.disabled :deep(.q-field__native) {
    background: #f3f4f6;
    color: #9ca3af;
  }
}
</style>

<style lang="scss">
// Dark mode support
body.body--dark {
  .doc-name {
    &.disabled {
      color: var(--muted-foreground);
    }
  }
}
</style>
